<?php
// Dashboard display values and chart datasets.
use App\Core\View;

$habitPercent = $habitTotals['total'] > 0 ? (int)round(($habitTotals['completed'] / $habitTotals['total']) * 100) : 0;
$icons = ['exercise' => 'bi-activity','diary' => 'bi-journal-bookmark','money' => 'bi-cash-stack','habit' => 'bi-bullseye'];
$moduleImages = ['exercise' => 'module-exercise-large.png','diary' => 'module-diary-large.png','money' => 'module-money-large.png','habit' => 'module-habit-large.png'];
