$categoryValues = array_map('floatval', array_column($categories, 'amount'));
$assetBase = View::e($baseUrl).'/assets/images';
?>
<section class="page-heading"><div><p class="page-eyebrow">Student overview</p><h1>Welcome back, <?= View::e($username) ?></h1><p class="page-subtitle">Get a clear overview of your routines, reflections, spending, and habits in one place.</p></div></section>
<section class="filter-panel mb-4"><form method="get" id="dashboardFilter" class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label" for="range">Dashboard period</label><select class="form-select" id="range" name="range"><option value="month" <?= $range === 'month' ? 'selected' : '' ?>>Recent 1 Month</option><option value="quarter" <?= $range === 'quarter' ? 'selected' : '' ?>>Recent 3 Months</option><option value="all" <?= $range === 'all' ? 'selected' : '' ?>>All Time</option><option value="custom" <?= $range === 'custom' ? 'selected' : '' ?>>Custom Date Range</option></select></div><div class="col-md-8"><p class="text-muted mb-2 small"><i class="bi bi-info-circle me-1"></i>Showing <?= View::e($periodLabel) ?>. Habit completion reflects the current status of all your habits.</p></div><div class="col-12 row g-3 <?= $range === 'custom' ? '' : 'd-none' ?>" id="customDateRange"><div class="col-md-4"><label class="form-label" for="start_date">Start Date</label><input class="form-control" id="start_date" type="date" name="start_date" value="<?= View::e($customStart) ?>"></div><div class="col-md-4"><label class="form-label" for="end_date">End Date</label><input class="form-control" id="end_date" type="date" name="end_date" value="<?= View::e($customEnd) ?>"></div></div><?php if ($filterError): ?><div class="col-12"><p class="text-danger small mb-0"><?= View::e($filterError) ?></p></div><?php endif; ?></form></section>
<section class="stats-grid"><?php foreach ([['exercise','Exercises',$monthly['exercises'],$periodLabel,'stat-card-primary'],['diary','Diary Entries',$monthly['diary_entries'],$periodLabel,'stat-card-primary'],['money','Total Expenses','RM '.number_format((float)$monthly['expenses'], 2),$periodLabel,'stat-card-success'],['habit','Habit Progress',$habitPercent.'%',(int)$habitTotals['completed'].' / '.(int)$habitTotals['total'].' completed','stat-card-warning']] as [$module,$label,$value,$detail,$class]): ?><a class="stat-card <?= $class ?>" href="<?= View::e($baseUrl) ?>/<?= $module ?>"><div><p><?= $label ?></p><h2><?= $value ?></h2><small class="text-muted"><?= View::e($detail) ?></small></div><span class="stat-icon"><img class="dashboard-stat-image" src="<?= $assetBase ?>/modules/<?= $moduleImages[$module] ?>" alt="<?= $label ?>"></span></a><?php endforeach; ?></section>
<section class="dashboard-grid"><article class="content-card"><div class="card-section-heading"><div><p class="card-kicker"><?= View::e($periodLabel) ?></p><h2>Recent Activities</h2></div></div><?php if ($recentActivities): ?><ul class="activity-list"><?php foreach ($recentActivities as $item): ?><li class="activity-item"><span class="activity-symbol activity-<?= View::e($item['module']) ?>"><i class="bi <?= $icons[$item['module']] ?>"></i></span><a class="activity-copy" href="<?= View::e($baseUrl) ?>/<?= View::e($item['url']) ?>"><strong><?= View::e($item['title']) ?></strong><small><?= View::e($item['detail']) ?></small></a><span class="activity-date"><?= View::e(date('d M', strtotime($item['date']))) ?></span></li><?php endforeach; ?></ul><?php else: ?><div class="empty-state"><img class="empty-state-image" src="<?= $assetBase ?>/illustrations/illustration-empty-state.png" alt=""><h3>No activity in this period</h3><p>Try another period or add data in one of the modules.</p></div><?php endif; ?></article><article class="content-card p-0 overflow-hidden"><div class="card-section-heading"><div><p class="card-kicker"><?= View::e($periodLabel) ?></p><h2>Activity Overview</h2></div></div><fieldset class="activity-chart-filters" id="activityChartFilters"><legend>Show data</legend><label class="activity-chart-filter activity-chart-filter-all"><input type="checkbox" data-select-all checked><span class="activity-chart-color activity-chart-color-all" aria-hidden="true"></span><span>All</span></label><label class="activity-chart-filter"><input type="checkbox" data-dataset-index="0" checked><span class="activity-chart-color activity-chart-color-exercise" aria-hidden="true"></span><span>Exercises</span></label><label class="activity-chart-filter"><input type="checkbox" data-dataset-index="1" checked><span class="activity-chart-color activity-chart-color-diary" aria-hidden="true"></span><span>Diary Entries</span></label><label class="activity-chart-filter"><input type="checkbox" data-dataset-index="2" checked><span class="activity-chart-color activity-chart-color-expense" aria-hidden="true"></span><span>Expenses (RM)</span></label></fieldset><div class="chart-area"><canvas id="dashboardChart"></canvas></div></article><article class="content-card chart-card"><p class="card-kicker"><?= View::e($periodLabel) ?></p><h2>Expense Categories</h2><?php if ($categories): ?><canvas id="categoryChart"></canvas><?php else: ?><p class="text-muted mb-0">No expenses in this period. <a href="<?= View::e($baseUrl) ?>/money">Open Money Tracker</a>.</p><?php endif; ?></article><article class="content-card"><div class="card-section-heading"><div><p class="card-kicker">Your schedule</p><h2>Upcoming Habits</h2></div><a class="small" href="<?= View::e($baseUrl) ?>/habit">View all</a></div><?php foreach ($habitPreview as $habit): ?><div class="habit-preview-row"><i class="bi bi-calendar-check"></i><div><strong><?= View::e($habit['habit_name']) ?></strong><small><?= View::e($habit['frequency']) ?><?php if ($habit['schedule_time']): ?> · <?= View::e(substr($habit['schedule_time'], 0, 5)) ?><?php endif; ?> · <?= (int)$habit['streak'] ?> day streak</small></div></div><?php endforeach; ?><?php if (!$habitPreview): ?><p class="text-muted mb-0">No habits yet. <a href="<?= View::e($baseUrl) ?>/habit/create">Create your first habit</a>.</p><?php endif; ?></article></section>
<section class="content-card mb-3"><div class="card-section-heading"><div><p class="card-kicker">Exercise module · <?= View::e($periodLabel) ?></p><h2>Exercise Snapshot</h2></div><a class="small" href="<?= View::e($baseUrl) ?>/exercise">Open Exercise Tracker</a></div><div class="row g-3 px-3 pb-3"><div class="col-lg-5"><div class="row g-3"><div class="col-4"><small class="text-muted d-block">Workouts</small><strong class="fs-4"><?= (int)$exerciseSnapshot['workouts'] ?></strong></div><div class="col-4"><small class="text-muted d-block">Duration</small><strong class="fs-4"><?= (int)$exerciseSnapshot['minutes'] ?> <small>min</small></strong></div><div class="col-4"><small class="text-muted d-block">Calories</small><strong class="fs-4"><?= number_format((float)$exerciseSnapshot['calories'], 0) ?> <small>kcal</small></strong></div></div><div class="pt-3 small text-muted"><?php if ($exerciseSnapshot['top_activity']): ?><p class="mb-1"><i class="bi bi-trophy me-1 text-warning"></i>Most frequent: <strong><?= View::e($exerciseSnapshot['top_activity']) ?></strong></p><?php endif; ?><?php if ($exerciseSnapshot['latest']): ?><p class="mb-0"><i class="bi bi-clock-history me-1 text-primary"></i>Latest: <strong><?= View::e($exerciseSnapshot['latest']['activity_type']) ?></strong> · <?= (int)$exerciseSnapshot['latest']['duration_minutes'] ?> min · <?= number_format((float)$exerciseSnapshot['latest']['calories_burned'], 0) ?> kcal</p><?php else: ?><p class="mb-0">No exercise records in this range.</p><?php endif; ?></div></div><div class="col-lg-7"><div class="dashboard-calorie-chart"><canvas id="caloriesChart"></canvas></div></div></div></section>
<section class="content-card motivation-card mb-3"><div><p class="card-kicker">Motivation</p><h2>Keep moving forward</h2><p>Small progress every day leads to big results.</p></div><img class="motivation-illustration" src="<?= $assetBase ?>/illustrations/illustration-dashboard-motivation.png" alt="" aria-hidden="true" loading="lazy"></section>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const dashboardCanvas=document.getElementById('dashboardChart');if(dashboardCanvas){new Chart(dashboardCanvas,{type:'line',data:{labels:<?= json_encode($chart['labels']) ?>,datasets:[{label:'Exercises',data:<?= json_encode($chart['exercises']) ?>,borderColor:'#6547e8',tension:.35,fill:false},{label:'Diary Entries',data:<?= json_encode($chart['diary']) ?>,borderColor:'#3182ce',tension:.35,fill:false},{label:'Expenses (RM)',data:<?= json_encode($chart['expenses']) ?>,borderColor:'#28a96b',tension:.35,fill:false,yAxisID:'y1'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{precision:0}},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false}}}}});}const categoryCanvas=document.getElementById('categoryChart');if(categoryCanvas){new Chart(categoryCanvas,{type:'doughnut',data:{labels:<?= json_encode($categoryLabels) ?>,datasets:[{data:<?= json_encode($categoryValues) ?>,backgroundColor:['#6547e8','#3182ce','#28a96b','#f5a623','#e84a5f','#7c6ea8']}]},options:{plugins:{legend:{position:'bottom'}}}});}const rangeSelect=document.getElementById('range'),customDateRange=document.getElementById('customDateRange'),dashboardFilter=document.getElementById('dashboardFilter'),customStart=document.getElementById('start_date'),customEnd=document.getElementById('end_date');if(rangeSelect){rangeSelect.addEventListener('change',()=>{const custom=rangeSelect.value==='custom';customDateRange.classList.toggle('d-none',!custom);if(!custom)dashboardFilter.requestSubmit();});[customStart,customEnd].forEach(input=>input&&input.addEventListener('change',()=>{if(customStart.value&&customEnd.value)dashboardFilter.requestSubmit();}));}const caloriesCanvas=document.getElementById('caloriesChart');if(caloriesCanvas){new Chart(caloriesCanvas,{type:'bar',data:{labels:<?= json_encode($chart['labels']) ?>,datasets:[{label:'kcal burned',data:<?= json_encode($chart['calories']) ?>,backgroundColor:'#6547e8',borderRadius:6,maxBarThickness:34}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,title:{display:true,text:'kcal'}}}}});}</script>
